module.exports = "<div class=\"card-header text-uppercase bg-dark text-white\">\n    <h5 style=\"border-bottom: 0;\">B2B Activity report</h5>\n</div>\n<div class=\"card\">\n    <form [formGroup]=\"regConfig\">\n        <div>\n            <div class=\"form-row\">\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <label for=\"appReference\">Application Reference</label>\n                        <input formControlName=\"app_reference\" type=\"text\"\n                            class=\"form-control text-uppercase form-control-sm nrm_input\"\n                            placeholder=\"Application Reference\" id=\"appReference\">\n                    </div>\n                </div>\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <label for=\"phone\">Phone</label>\n                        <input formControlName=\"phone_number\" type=\"text\"\n                            class=\"form-control text-uppercase form-control-sm nrm_input\" placeholder=\"Phone\"\n                            (keypress)=\"numberOnly($event)\" id=\"phone\">\n                    </div>\n                </div>\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <label for=\"email\">Email</label>\n                        <input formControlName=\"email\" type=\"email\" class=\"form-control form-control-sm nrm_input\"\n                            placeholder=\"Email\" id=\"email\">\n                    </div>\n                </div>\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <label for=\"bookedBy\">Status</label>\n                        <select formControlName=\"status\" name=\"cars\" id=\"bookedBy\"\n                            class=\"form-control form-control-sm nrm_input\">\n                            <option value=\"ALL\">ALL</option>\n                            <option value=\"BOOKING_CONFIRMED\">CONFIRMED</option>\n                            <option value=\"ticked\">TICKED</option>\n                            <option value=\"BOOKING_CANCELLED\">CANCELLED</option>\n                            <option value=\"cancelInProgress\">CANCELLATION IN PROGRESS</option>\n                            <option value=\"failed\">FAILED</option>\n                            <option value=\"BOOKING_HOLD\">HOLD</option>\n                            <option value=\"BOOKING_INPROGRESS\">IN PROGRESS</option>\n                        </select>\n                        <div>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <span class=\"icon depart_date\" (click)=\"isOpen= !isOpen\"></span>\n                        <label for=\"fromDate\">Booked From Date</label>\n                        <input formControlName=\"booked_from_date\" type=\"text\" id=\"fromDate\" autocomplete=\"off\"\n                            class=\"form-control form-control-sm nrm_input\" placement=\"bottom left\"\n                            placeholder=\"dd/mm/yyyy\" bsDatepicker [bsConfig]=\"bsDateConf\" [isOpen]=\"isOpen\"\n                            >\n                    </div>\n                </div>\n                <div class=\"col-4 pr-0\">\n                    <div class=\"form-group\">\n                        <span class=\"icon depart_date\" (click)=\"isOpen= !isOpen\"></span>\n                        <label for=\"toDate\">Booked To Date</label>\n                        <input formControlName=\"booked_to_date\" type=\"text\" id=\"toDate\" autocomplete=\"off\"\n                            class=\"form-control form-control-sm nrm_input\" placement=\"bottom left\"\n                            placeholder=\"dd/mm/yyyy\" bsDatepicker [bsConfig]=\"bsDateConf\" [isOpen]=\"isOpen\"\n                          >\n                    </div>\n                </div>\n            </div>\n            <div class=\"btncontainer\">\n                <button type=\"submit\" class=\"btnStyle\" (click)=\"onSearchSubmit()\">Search</button> &nbsp;\n                <button type=\"button\" class=\"btnStyle\" (click)=\"onReset()\">Reset</button>\n            </div>\n        </div>\n    </form>\n</div>\n<div class=\"card\" style=\"margin-top: 30px;\">\n    <div class=\"card-body\">\n        <div style=\"padding-bottom: 15px;\">\n            <p>Total {{respData?.length}} Bookings</p>\n            <button class=\"btnStyle\" (click)=\"downloadPdf()\">PDF</button>&nbsp;\n            <button class=\"btnStyle\" (click)=\"download('xlsx', 'portrait')\">Export to excel</button>\n            <div class=\"form-group mb-0 col-sm-3 p-0 float-right has-search\">\n                <span class=\"fa fa-search form-control-feedback\"></span>\n                <input class=\"form-control\" type=\"text\" name=\"Search\" [(ngModel)]=\"searchText\"\n                    autocomplete=\"off\" placeholder=\"Search\">\n            </div>\n        </div>\n        <div class=\"mb-3\">\n            <form>\n                <div class=\"wrapper1\" id=\"notifications-list\" (scroll)=\"scrollTwo.scrollLeft = scrollOne.scrollLeft\"\n                    #scrollOne>\n                    <div class=\"div1\"></div>\n                </div>\n\n                <div class=\"wrapper2\" #scrollTwo (scroll)=\"scrollOne.scrollLeft = scrollTwo.scrollLeft\">\n                    <div class=\"div2 invisible-scrollbar\">\n                        <div class=\"table-respons\">\n                            <table class=\"table table-borderless table-striped table-hover\" matSort\n                                (matSortChange)=\"sortData($event)\" id=\"b2b-activity-report\">\n                                <thead>\n                                    <tr>\n                                        <th scope=\"col\" class=\"text-left text-nowrap\"\n                                            *ngFor=\"let header of displayColumn;\">\n                                            {{header.value }}\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr *ngIf=\"noData\">\n                                        <td colspan=\"11\">\n                                            <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\"\n                                                mode=\"indeterminate\"></mat-spinner>\n                                        </td>\n                                    </tr>\n                                    <tr\n                                        *ngIf=\"!noData && (!respData.length || (respData | filter:searchText).length === 0)\">\n                                        <td colspan=\"11\">\n                                            <h4 class=\"text-muted text-center\">\n                                                No Data Found!\n                                            </h4>\n                                        </td>\n                                    </tr>\n                                    <tr\n                                    *ngFor=\"let data of respData | filter:searchText | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                                    <td class=\"text-left text-muted\">{{i+1}}.</td>\n                                    <td class=\"text-left overflow-hidden\">\n                                        <div ngbDropdown container=\"body\"><button class=\"btnStyle\"\n                                                ngbDropdownToggle>\n                                                {{'Action'}}\n                                            </button>\n                                            <div ngbDropdownMenu>\n                                                <button ngbDropdownItem\n                                                    (click)=\"onActivityRedirect(data?.BookingDetails.AppReference,'voucher')\">View\n                                                    Voucher</button>\n                                                <button ngbDropdownItem\n                                                    (click)=\"onActivityRedirect(data?.BookingDetails.AppReference,'invoice')\">View\n                                                    Invoice</button>\n                                                <button ngbDropdownItem (click)=\"showPaxProfile(data)\">Pax\n                                                    Profile</button>\n                                                <button\n                                                    *ngIf=\"data?.BookingDetails.ConfirmationReference && (data?.BookingDetails.Status == 'BOOKING_CONFIRMED'|| data?.BookingDetails.Status == 'BOOKING_FAILED' || data?.BookingDetails.Status == 'BOOKING_VOIDED' || data?.BookingDetails.Status =='BOOKING_HOLD')\"\n                                                    ngbDropdownItem (click)=\"cancelTicketPopup(data)\"> Cancel\n                                                </button>\n\n                                                <button\n                                                    *ngIf=\"data?.BookingDetails.ConfirmationReference && (data?.BookingDetails.Status == 'BOOKING_CONFIRMED')\"\n                                                    ngbDropdownItem (click)=\"showUpdateGuideInfoModal(data)\"> Update Guide Info\n                                                </button>\n                                                <!-- <button\n                                                *ngIf=\"data?.BookingDetails.Status === 'BOOKING_CANCELLED'\"\n                                                ngbDropdownItem\n                                                (click)=\"refundTicketPopup(data)\">\n                                                Refund\n                                              </button>                                               -->\n                                            </div>\n                                        </div>\n                                    </td>\n                                    <td class=\"text-left\">\n                                        <span *ngIf=\"data['BookingDetails']['Status'] == 'BOOKING_FAILED'\" class=\"badge badge-danger\">\n                                            Booking Failed\n                                        </span>\n                                        <span *ngIf=\"data['BookingDetails']['Status'] == 'BOOKING_CONFIRMED'\"\n                                            class=\"badge badge-success\">\n                                            Booking Confirmed\n                                        </span>\n                                        <span *ngIf=\"data['BookingDetails']['Status'] == 'BOOKING_CANCELLED'\"\n                                            class=\"badge badge-danger\">\n                                            Booking Cancelled\n                                        </span>\n                                        <span *ngIf=\"data['BookingDetails']['Status']== 'BOOKING_INPROGRESS'\"\n                                            class=\"badge badge-info\">\n                                            Booking Inprogress\n                                        </span>\n                                        <span *ngIf=\"data['BookingDetails']['Status'] == 'BOOKING_HOLD'\"\n                                        class=\"badge badge-warning\">\n                                        Booking Hold\n                                    </span>\n                                        {{data['BookingDetails']['Status'] ? '' : 'N/A'}}\n                                    </td>\n                                    <td class=\"text-left\" *ngIf=\"loggerUserAuthId !== 7\">\n                                        {{(data?.BookingDetails?.bundle_booking === '1' || data?.BookingDetails?.bundle_booking === 1) ? \"Bundle Booking\" : \"Normal Booking\"}}\n                                    </td>\n                           \n                                    <td class=\"text-left\"> {{data?.BookingDetails.AppReference}} </td>\n                                    <td class=\"text-left\">{{data?.BookingDetails.ConfirmationReference || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{data?.BookingDetails.supplierName || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data?.BookingDetails.AgentName || 'N/A'}} </td>\n                                    <td class=\"text-left\"> {{data.BookingDetails.PaymentMode  !== '' ? data.BookingDetails.PaymentMode : 'N/A'   }} \n                                        <span *ngIf=\"data?.BookingDetails.PaymentStatus == 'Paid' && data.BookingDetails.PaymentMode !== 'wallet'\"> - {{data?.BookingDetails.PaidMode || 'N/A'}}</span>\n                                    </td>\n                                    <td class=\"text-left\"> {{data?.BookingDetails.PaidOn || 'N/A'}} </td>\n                                    \n                        <td class=\"text-left\"> {{data.BookingDetails.PaymentStatus}} \n                                    </td>\n                                    <td class=\"text-left\">{{data.BookingPaxDetails[0]?.Title}} {{data.BookingPaxDetails[0]?.FirstName}}\n                                        {{data.BookingPaxDetails[0]?.LastName}} </td>\n                                    <!-- <td class=\"text-left\" >{{data.BookingDetails?.Email || 'N/A'}} </td> -->\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.Email || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.AgentNumber || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{getPaxData(data.BookingDetails?.searchData?.paxes[0]) || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{data.BookingItenaryDetails?.attributes?.ProductName || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.ModalityName || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{data.BookingItenaryDetails?.city || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{data.BookingItenaryDetails?.country || 'N/A'}} </td>\n                                    <td class=\"text-left\">{{data.BookingDetails?.travelDate | date: 'dd/MM/yyyy'}} </td>\n                                    <td class=\"text-left\">{{data.BookingDetails?.toDate | date: 'dd/MM/yyyy'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.TotalNet || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.AdminMarkup || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\">{{data.BookingDetails?.AgentMarkup || 'N/A'}} </td>\n                                    <td class=\"text-left\"  *ngIf=\"loggerUserAuthId !== 7\"> {{data?.BookingDetails.Currency  }} </td>\n                                    <td class=\"text-left\"> {{data?.BookingDetails?.supplier_total_price  || 0 }} {{data?.BookingDetails?.supplier_currency || ''}} </td>\n                                    <td class=\"text-left\"> {{data?.BookingDetails.CreatedDatetime | date: 'dd/MM/yyyy'}} </td>\n                                    <td class=\"text-left\"> {{data?.BookingDetails?.GuideName ?  data?.BookingDetails?.GuideName : ''}} {{data?.BookingDetails?.GuideContact ? '('+ data?.BookingDetails?.GuideContact + ')' : ''}}</td>\n                                    <td class=\"text-left\"> {{data?.BookingDetails.cancellation_deadline | date: 'dd/MM/yyyy'}}</td>\n                                    <td class=\"text-left\">\n                                        <ng-container *ngIf=\"data?.BookingDetails.Status === 'BOOKING_CANCELLED'; else naTemplate\">\n                                            {{ data?.BookingDetails.cancelled_datetime | date: 'dd/MM/yyyy' }}\n                                        </ng-container>\n                                        <ng-template #naTemplate>NA</ng-template>\n                                    </td>\n                                    <td class=\"text-left\">{{data?.BookingDetails.CancelAmount }} </td>                                 \n                                </tr>\n                                </tbody>\n                            </table>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"loadWrapper1\" *ngIf=\"load\">\n                    <div class=\"loader1\"></div>\n                </div>\n                <div class=\"card-footer pb-0\">\n                    <div class=\"d-flex w-100 justify-content-between\">\n                        <ngb-pagination [collectionSize]=\"collectionSize\" [(page)]=\"page\" [pageSize]=\"pageSize\">\n                        </ngb-pagination>\n                        <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                            <option [ngValue]=\"50\">50 items per page</option>\n                            <option [ngValue]=\"100\">100 items per page</option>\n                            <option [ngValue]=\"150\">150 items per page</option>\n                            <option [ngValue]=\"200\">200 items per page</option>\n                            <option [ngValue]=\"500\">500 items per page</option>\n                            <option [ngValue]=\"700\">700 items per page</option>\n                            <option [ngValue]=\"1000\">1000 items per page</option>\n                        </select>\n                    </div>\n                </div>\n            </form>\n        </div>\n    </div>\n</div>\n\n<!-- The Modal -->\n<div class=\"modal\" id=\"paxProfile\" [style.display]=\"showModal ? 'block' : 'none'\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\">\n\n            <!-- Modal Header -->\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">User Details:</h4>\n                <button type=\"button\" class=\"close\" data-dismiss=\"modal\" (click)=\"hide()\">&times;</button>\n            </div>\n\n            <!-- Modal body -->\n            <div class=\"modal-body\">\n                <h5>Lead Traveler Information</h5>\n                <p>Title : {{paxDetails?.Title}}</p>\n                <p>Firstname : {{paxDetails?.FirstName}}</p>\n                <p>Lastname : {{paxDetails?.LastName}}</p>\n                <!-- <p>Email : {{paxDetails?.Email}}</p> -->\n            </div>\n\n            <!-- Modal footer -->\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btnStyle\" data-dismiss=\"modal\" (click)=\"hide()\">Close</button>\n            </div>\n\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"cancelPolicy\" [style.display]=\"showCancelModal ? 'block' : 'none'\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\">\n\n            <!-- Modal Header -->\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Cancellation Policy</h4>\n                <button type=\"button\" class=\"close\" data-dismiss=\"modal\" (click)=\"hide()\">&times;</button>\n            </div>\n\n            <!-- Modal body -->\n            <div class=\"modal-body\">\n                {{\"From 06 Jan 2021,USD 25 will be charged as cancellation penalty.\"}}\n            </div>\n\n            <!-- Modal footer -->\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btnStyle\" data-dismiss=\"modal\" (click)=\"hide()\">Close</button>\n            </div>\n\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"confirmModal\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"confirmModalLabel\" aria-hidden=\"true\"\n    [style.display]=\"showConfirm ? 'block' : 'none'\">\n    <div class=\"modal-dialog  modal-sm\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"paymentModalLabel\">Confirm</h5>\n                <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-label=\"Close\" (click)=\"hide()\">\n                    <span aria-hidden=\"true\">&times;</span>\n                </button>\n            </div>\n            <div class=\"modal-body\">\n                <p>Do you really want to {{subjectName}} the booking?</p>\n            </div>\n            <div class=\"modal-footer\" style=\"justify-content: space-between;\">\n                <button type=\"button\" class=\"btn btn-success\" *ngIf=\"subjectName=='Cancel'\"\n                    (click)=\"cancelTicket()\">Yes</button>\n                <button type=\"button\" class=\"btn btn-success\" *ngIf=\"subjectName=='Refund'\"\n                    (click)=\"refundTicket()\">Yes</button>\n                <button type=\"button\" class=\"btn btn-danger\" data-dismiss=\"modal\" (click)=\"hide()\">No</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n\n<div class=\"modal\" id=\"confirmModal\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"confirmModalLabel\" aria-hidden=\"true\"\n    [style.display]=\"showUpdateGuideInfo ? 'block' : 'none'\">\n    <div class=\"modal-dialog  modal-sm\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"paymentModalLabel\">Guide Information</h5>\n                <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-label=\"Close\" (click)=\"hide()\">\n                    <span aria-hidden=\"true\">&times;</span>\n                </button>\n            </div>\n            <div class=\"modal-body\">\n\n                <div class=\"col-12\">\n                    <label>Guide Name</label>\n                    <input class=\"form-control\" type=\"text\" name=\"Search\" [(ngModel)]=\"driverName\"\n                        autocomplete=\"off\" placeholder=\"Enter Guide Name\"/>\n                </div>\n\n                <div class=\"col-12\">\n                    <label>Guide Contact Number</label>\n                    <input class=\"form-control\" type=\"text\" name=\"Search\" [(ngModel)]=\"driverMobile\"\n                        autocomplete=\"off\" placeholder=\"Enter Guide contact Number\"/>\n                </div>\n                \n            </div>\n            <div class=\"modal-footer\" style=\"justify-content: space-between;\">\n                <button type=\"button\" class=\"btn btn-success\" \n                    (click)=\"subminGuideInfo()\">Update</button>\n                <button type=\"button\" class=\"btn btn-danger\" data-dismiss=\"modal\" (click)=\"hide()\">No</button>\n            </div>\n        </div>\n    </div>\n</div>";

