"use strict";
module.exports = "<div style=\"background:#ccc; width:100%; padding:40px 0px; position:relative\" *ngIf=\"voucherData\">\n    <table style=\"width:100%;max-width: 900px;margin: 0 auto;padding: 0px; background-color: #f3f3f3;\">\n        <tbody>\n            <tr>\n                <td colspan=\"2\">\n                    <table\n                        style=\"width: 100%;border-bottom: 2px solid #e8e8e8;padding: 10px 10px;background-color: #f5f5f5;\">\n                        <tbody>\n                            <tr>\n\n                                <td style=\"text-align: left; padding: 10px;\" colspan=\"2\">\n                                    <img src=\"assets/images/logo_white.png\" style=\"background: #000; width: 60px;\">\n                                </td>\n\n                                <td style=\"color: #333; line-height: 20px; padding:10px; text-align: right;\"\n                                    colspan=\"2\">\n                                    <span style=\"margin: 0px; float: right; font-size: 14px; font-weight: bold\">Booking\n                                        Ref - {{voucherData['AppReference']}}</span>\n                                    <br>\n                                    <p style=\"margin: 0;font-size: 13px;color: #2196f3; font-weight: bold;\">Supplier -\n                                        {{voucherData['CarSupplierName']}}</p> <br>\n                                    <span style=\"margin: 0px; float: right; font-size: 14px; font-weight: bold\">Car Name\n                                        - {{voucherData['CarName']}}</span>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 20px;\">\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <h4 style=\"color: #000;margin: 0px; font-weight: bold; font-size: 16px; padding: 5px 0px;\">Car\n                        Details</h4>\n                </td>\n            </tr>\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <table cellspacing=\"0\"\n                        style=\"width: 100%;color: #000;font-size: 13px; text-align: left;margin-top: 10px;\">\n                        <tbody>\n                            <tr style=\"margin: 0; color:#fff; background-color: #000;padding: 10px;\">\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #df9612;width: 20%;\">Pick-up\n                                    Location</th>\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #000;width: 20%;\">Pick-up\n                                    Date/Time</th>\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #000;width: 20%;\">Drop-Off\n                                    Location</th>\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #df9612;width: 20%;\">Drop-Off\n                                    Date/Time</th>\n                            </tr>\n\n                            <tr style=\"font-size: 15px;\">\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{voucherData['CarPickupAddress']}}</p>\n                                </td>\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{voucherData['CarFromDate'] | date}}\n                                        {{voucherData['PickUpTime']}}</p>\n                                </td>\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{voucherData['CarDropAddress']}}</p>\n                                </td>\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{voucherData['CarToDate'] | date}}\n                                        {{voucherData['DropTime']}}</p>\n                                </td>\n                            </tr>\n                            <tr>\n                                <td colspan=\"2\"\n                                    style=\"border-top: 2px solid #000;padding-right: 0px; font-size:14px; line-height: 23px; vertical-align: top;\">\n                                    <p style=\"margin: 0;\"><b>Booked by :</b></p>\n                                    <p style=\"margin: 0;\">{{voucherData['PassengerDetails'][0]['first_name'] + ' '+\n                                        voucherData['PassengerDetails'][0]['last_name']}},</p>\n                                    <p style=\"margin: 0;\">{{voucherData['PassengerDetails'][0]['adress1']}}</p>\n                                    <p style=\"margin: 0;\">mani@gmail.com,</p>\n                                    <p style=\"margin: 0;\">{{voucherData['PhoneNumber']}}</p>\n                                </td>\n                                <td colspan=\"2\" style=\"border-top: 2px solid #000;padding-right: 70px; font-size:14px;\">\n                                    <p style=\"text-align: right;margin:7px 0;\"><label\n                                            style=\"text-align: left; padding: 0 0px 0 0;\">Rental Cost</label><span\n                                            style=\"width: 120px;display: inline-block;\">{{voucherData['Currency']}}\n                                            {{voucherData['TotalFare']}}</span></p>\n                                    <p style=\"text-align: right;margin:0 0 0px 0;\"><b><label\n                                                style=\"padding: 0px 0px 0px 0px;\">Total Rental Price</label><span\n                                                style=\"width: 120px;display: inline-block;\">{{voucherData['Currency']}}\n                                                {{voucherData['TotalFare']}}</span></b></p>\n                                    <p style=\"text-align: right;margin:0 0 7px 0;\"><b><label\n                                                style=\"padding: 0px 0px 0px 0px;\">Coupon Discount</label><span\n                                                style=\"width: 120px;display: inline-block;\">{{voucherData['Currency']}}\n                                                0.00</span></b></p>\n                                    <p style=\"text-align: right;margin:13px 0 7px 0;\"><b\n                                            style=\"padding-top: 5px; border-top: 1px solid #ccc;\"><label\n                                                style=\"padding: 0px 0px 0px 0px;\">Amount Paid</label><span\n                                                style=\"width: 120px;display: inline-block;\">{{voucherData['Currency']}}\n                                                {{voucherData['TotalFare']}}</span></b></p>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <h4 style=\"color: #000;margin: 0px; font-weight: bold; font-size: 16px; padding: 5px 0px;\">Passenger\n                        Details</h4>\n                </td>\n            </tr>\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <table cellspacing=\"0\"\n                        style=\"width: 100%;color: #000;font-size: 13px; text-align: left;margin-top: 10px;\">\n                        <tbody>\n                            <tr style=\"margin: 0; color:#fff; background-color: #000;padding: 10px;\">\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #df9612;width: 20%;\">Passenger\n                                    Name</th>\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #000;width: 20%;\">Phone</th>\n                                <th style=\"padding: 10px 8px;border-bottom: 1px solid #000;width: 20%;\">Age</th>\n                            </tr>\n\n                            <tr style=\"font-size: 15px;\" *ngFor=\"let user of voucherData['PassengerDetails']\">\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{user['first_name'] +' '+user['last_name']}}</p>\n                                </td>\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{user['phone']}}</p>\n                                </td>\n                                <td style=\"border-bottom: 1px solid #000;\">\n                                    <p style=\"margin: 9px 0px;\">{{user['date_of_birth']}}</p>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <h4\n                        style=\"color: #000; font-weight: bold;margin-bottom: 10px;  font-size: 15px; border-bottom: 2px solid #585858;  padding: 10px 0px; text-transform: uppercase;\">\n                        Terms &amp; Conditions</h4>\n                </td>\n            </tr>\n            <tr>\n                <td style=\"color: #000;font-size: 12px;padding: 0 15px;\" colspan=\"2\">\n                    <p>Guarantee - GUARANTEED FOR 365 DAYS</p>\n                </td>\n            </tr>\n\n            <tr>\n                <td style=\"color: #000;font-size: 12px;padding: 0 15px;\" colspan=\"2\">\n                    <p>General - MUST RETURN TO THE SAME STATE</p>\n                </td>\n            </tr>\n            <tr>\n                <td style=\"color: #000;font-size: 12px;padding: 0 15px;\" colspan=\"2\">\n                    <p>General - THE MINIMUM RENTAL PERIOD IS 001 DAYS</p>\n                </td>\n            </tr>\n\n            <tr>\n                <td colspan=\"2\" style=\"padding: 0 15px;\">\n                    <h4\n                        style=\"color: #000; font-weight: bold;margin-bottom: 10px;  font-size: 15px; border-bottom: 2px solid #585858;  padding: 10px 0px; text-transform: uppercase;\">\n                        Cancellation Policy</h4>\n                </td>\n            </tr>\n            <tr>\n                <td style=\"color: #000;font-size: 12px;padding: 0 15px;\" colspan=\"2\">\n                    <p>Up to 48hours before pick-up, cancellation free of charge. Within 48hours prior to pick-up and in\n                        the event of a no-show 100% of the sales price will be charged.</p>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n</div>";

