/***/ 88862:
/*!*********************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/report/B2C/b2c/b2c-bus/component/bus-invoice/bus-invoice.component.html?ngResource ***!
  \*********************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner bus-document\" *ngIf=\"bookingData\">\n  <div class=\"document-header\">\n    <img src=\"assets/images/tour-bro.png\" alt=\"Tourbro\">\n    <div>\n      <h4>Bus Booking Details</h4>\n      <p>Reservation Code: <strong>{{ bookingData?.app_reference || 'N/A' }}</strong></p>\n    </div>\n  </div>\n\n  <h5>Booking Summary</h5>\n  <table class=\"table table-bordered\">\n    <tbody>\n      <tr>\n        <th>Status</th>\n        <td>{{ bookingData?.status || 'N/A' }}</td>\n        <th>Booked On</th>\n        <td>{{ itinerary?.created_at | date:'dd/MM/yyyy' }}</td>\n      </tr>\n      <tr>\n        <th>Booked By</th>\n        <td>{{ bookingData?.booked_by || 'N/A' }}</td>\n        <th>Booking Source</th>\n        <td>{{ bookingData?.booking_source || 'N/A' }}</td>\n      </tr>\n      <tr>\n        <th>PNR</th>\n        <td>{{ bookingData?.pnr || 'N/A' }}</td>\n        <th>Ticket</th>\n        <td>{{ bookingData?.ticket || 'N/A' }}</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <h5>Journey Details</h5>\n  <table class=\"table table-bordered\">\n    <tbody>\n      <tr>\n        <th>Departure From</th>\n        <td>{{ itinerary?.departure_from || 'N/A' }}</td>\n        <th>Arrival To</th>\n        <td>{{ itinerary?.arrival_to || 'N/A' }}</td>\n      </tr>\n      <tr>\n        <th>Departure Date/Time</th>\n        <td>{{ itinerary?.departure_datetime | date:'dd/MM/yyyy HH:mm' }}</td>\n        <th>Arrival Date/Time</th>\n        <td>{{ itinerary?.arrival_datetime | date:'dd/MM/yyyy HH:mm' }}</td>\n      </tr>\n      <tr>\n        <th>Bus Type</th>\n        <td>{{ itinerary?.bus_type || 'N/A' }}</td>\n        <th>Operator</th>\n        <td>{{ itinerary?.operator || 'N/A' }}</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <h5>Passenger Details</h5>\n  <table class=\"table table-bordered\" *ngIf=\"passengers?.length; else noPassengers\">\n    <thead>\n      <tr>\n        <th>Sl. No</th>\n        <th>Name</th>\n        <th>Age</th>\n        <th>Gender</th>\n        <th>Seat</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr *ngFor=\"let passenger of passengers; let i = index\">\n        <td>{{ i + 1 }}</td>\n        <td>{{ passenger?.name || passenger?.first_name || passenger?.FirstName || 'N/A' }}</td>\n        <td>{{ passenger?.age || passenger?.Age || 'N/A' }}</td>\n        <td>{{ passenger?.gender || passenger?.Gender || 'N/A' }}</td>\n        <td>{{ passenger?.seat_no || passenger?.seat || passenger?.SeatName || 'N/A' }}</td>\n      </tr>\n    </tbody>\n  </table>\n  <ng-template #noPassengers>\n    <p class=\"text-muted\">No passenger details available.</p>\n  </ng-template>\n\n  <h5>Fare Details</h5>\n  <table class=\"table table-bordered\">\n    <tbody>\n      <tr>\n        <th>Currency</th>\n        <td>{{ bookingData?.currency || 'N/A' }}</td>\n        <th>Total Fare</th>\n        <td>{{ bookingData?.total_fare | number:'1.2-2' }}</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<div class=\"card adminInner text-center\" *ngIf=\"!loading && !bookingData\">\n  No booking details found.\n</div>\n";

/***/ }),

